"use client";

import { useEffect, useMemo, useRef, useState } from "react";

export type ReceiptStatus = "clean" | "review" | "validated" | "blocked" | "pending" | "released" | "refunded" | "inspected";

export type ReceiptDetail = {
  id: string;
  title: string;
  operation: string;
  status: ReceiptStatus;
  timestamp?: string;
  accountState?: string;
  creditsReserved?: number;
  creditsCommitted?: number;
  creditsReleased?: number;
  inputSizeBucket?: string;
  originalHash?: string;
  outputHash?: string;
  findingsDetected?: number;
  findingsRemoved?: number;
  findingsPreserved?: number;
  findingsReview?: number;
  verification?: string;
  details?: Array<{ label: string; value: string | number }>;
  notes?: string[];
};

export function emitReceipt(detail: ReceiptDetail) {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new CustomEvent<ReceiptDetail>("provenance:receipt", {
    detail: { ...detail, timestamp: detail.timestamp ?? new Date().toISOString() },
  }));
}

function downloadReceipt(receipt: ReceiptDetail) {
  const blob = new Blob([JSON.stringify({ version: "ui-receipt-v2", ...receipt }, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = `provenance-receipt-${receipt.id.slice(0, 12)}.json`;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

function humanStatus(receipt: ReceiptDetail) {
  switch (receipt.status) {
    case "validated":
      return "Verified. The output passed the operation’s validation checks.";
    case "review":
      return "Inspection complete. Some evidence still needs review.";
    case "blocked":
      return "Action blocked so integrity-sensitive evidence is not silently damaged.";
    case "released":
      return "Validation did not complete, so the credit hold was released.";
    case "refunded":
      return "The billing event was reconciled and the eligible amount was refunded.";
    case "pending":
      return "The operation is recorded, but final reconciliation is still pending.";
    case "clean":
      return "Inspection complete. No tracked issue requires action.";
    default:
      return "Inspection complete. Evidence is ready to review.";
  }
}

function timelineFor(receipt: ReceiptDetail) {
  if (receipt.status === "released") return ["Inspect", "Reserve", "Validation failed", "Credits released"];
  if (receipt.status === "refunded") return ["Inspect", "Commit", "Reconcile", "Refunded"];
  if (receipt.status === "blocked") return ["Inspect", "Classify", "Blocked", "Receipt"];
  if (/\.(scan|inspect|verify)$/.test(receipt.operation) || receipt.operation === "file.inspect") {
    return ["Inspect", "Classify", "Verify", "Receipt"];
  }
  return ["Inspect", "Classify", "Act", "Verify", "Receipt"];
}

export function ReceiptDrawer() {
  const [receipt, setReceipt] = useState<ReceiptDetail | null>(null);
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement | null>(null);
  const closeRef = useRef<HTMLButtonElement | null>(null);

  useEffect(() => {
    const onReceipt = (event: Event) => {
      const detail = (event as CustomEvent<ReceiptDetail>).detail;
      if (!detail?.id || !detail?.operation) return;
      setReceipt(detail);
    };
    window.addEventListener("provenance:receipt", onReceipt);
    return () => window.removeEventListener("provenance:receipt", onReceipt);
  }, []);

  useEffect(() => {
    if (!open) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.requestAnimationFrame(() => closeRef.current?.focus());

    const close = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false);
        window.requestAnimationFrame(() => triggerRef.current?.focus());
      }
    };
    document.addEventListener("keydown", close);
    return () => {
      document.removeEventListener("keydown", close);
      document.body.style.overflow = previousOverflow;
    };
  }, [open]);

  const timeline = useMemo(() => receipt ? timelineFor(receipt) : [], [receipt]);
  if (!receipt) return null;

  const detected = receipt.findingsDetected ?? (
    typeof receipt.findingsRemoved === "number" || typeof receipt.findingsPreserved === "number"
      ? (receipt.findingsRemoved ?? 0) + (receipt.findingsPreserved ?? 0)
      : undefined
  );

  function closeDrawer() {
    setOpen(false);
    window.requestAnimationFrame(() => triggerRef.current?.focus());
  }

  return <>
    <button
      ref={triggerRef}
      type="button"
      className="receipt-fab"
      onClick={() => setOpen(true)}
      aria-label="View latest verification receipt"
    >
      <span className="status-dot"/>View receipt
    </button>

    {open && <div className="receipt-overlay" role="presentation" onMouseDown={(event) => {
      if (event.currentTarget === event.target) closeDrawer();
    }}>
      <aside className="receipt-drawer" role="dialog" aria-modal="true" aria-labelledby="receipt-drawer-title" aria-describedby="receipt-status-copy">
        <div className="receipt-drawer-grabber" aria-hidden="true" />
        <div className="receipt-drawer-head">
          <div><p className="eyebrow">Forensic ledger</p><h2 id="receipt-drawer-title">{receipt.title}</h2></div>
          <button ref={closeRef} className="icon-button" type="button" onClick={closeDrawer} aria-label="Close receipt">×</button>
        </div>

        <div className="receipt-status-summary">
          <div className="receipt-status-row">
            <span className={`receipt-status ${receipt.status}`}>{receipt.status}</span>
            <span className="mono-label">{receipt.operation}</span>
          </div>
          <p id="receipt-status-copy">{humanStatus(receipt)}</p>
        </div>

        <div className="receipt-timeline refined" aria-label="Receipt timeline">
          {timeline.map((stage, index) => <div className={receipt.status === "pending" && index === timeline.length - 1 ? "" : "active"} key={stage}>
            <span aria-hidden="true"/><strong>{stage}</strong>
          </div>)}
        </div>

        <div className="receipt-glance-grid" aria-label="Receipt summary">
          {typeof detected === "number" && <div><span>Detected</span><strong>{detected}</strong></div>}
          {typeof receipt.findingsRemoved === "number" && <div><span>Removed</span><strong>{receipt.findingsRemoved}</strong></div>}
          {typeof receipt.findingsPreserved === "number" && <div><span>Preserved</span><strong>{receipt.findingsPreserved}</strong></div>}
          {typeof receipt.findingsReview === "number" && <div><span>Review</span><strong>{receipt.findingsReview}</strong></div>}
          {typeof receipt.creditsCommitted === "number" && <div><span>Committed</span><strong>{receipt.creditsCommitted}</strong></div>}
          {typeof receipt.creditsReleased === "number" && <div><span>Released</span><strong>{receipt.creditsReleased}</strong></div>}
        </div>

        <dl className="receipt-ledger receipt-ledger-primary">
          <div><dt>Operation ID</dt><dd className="mono-label">{receipt.id}</dd></div>
          <div><dt>Timestamp</dt><dd>{receipt.timestamp ? new Date(receipt.timestamp).toLocaleString() : "Now"}</dd></div>
          {receipt.accountState && <div><dt>Account</dt><dd>{receipt.accountState}</dd></div>}
          {receipt.inputSizeBucket && <div><dt>Input size</dt><dd>{receipt.inputSizeBucket}</dd></div>}
        </dl>

        {(receipt.verification || typeof receipt.creditsReserved === "number" || typeof receipt.creditsCommitted === "number" || typeof receipt.creditsReleased === "number") && <div className="verification-box receipt-verification">
          <strong>Verification & credit state</strong>
          {receipt.verification && <p>{receipt.verification}</p>}
          {(typeof receipt.creditsReserved === "number" || typeof receipt.creditsCommitted === "number" || typeof receipt.creditsReleased === "number") && <div className="credit-state-timeline" aria-label="Receipt credit state">
            {typeof receipt.creditsReserved === "number" && <span className="done">reserved {receipt.creditsReserved}</span>}
            {typeof receipt.creditsCommitted === "number" && <><i aria-hidden="true">→</i><span className="done">committed {receipt.creditsCommitted}</span></>}
            {typeof receipt.creditsReleased === "number" && <><i aria-hidden="true">→</i><span className="released">released {receipt.creditsReleased}</span></>}
          </div>}
        </div>}

        {(receipt.originalHash || receipt.outputHash || receipt.details?.length) && <details className="receipt-advanced">
          <summary>Technical evidence <span>expand</span></summary>
          <dl className="receipt-ledger">
            {receipt.originalHash && <div><dt>Original SHA-256</dt><dd className="mono-label">{receipt.originalHash}</dd></div>}
            {receipt.outputHash && <div><dt>Output SHA-256</dt><dd className="mono-label">{receipt.outputHash}</dd></div>}
          </dl>
          {receipt.details?.length ? <div className="receipt-detail-grid">{receipt.details.map((item) => <div key={item.label}><span>{item.label}</span><strong>{item.value}</strong></div>)}</div> : null}
        </details>}

        {receipt.notes?.length ? <div className="notice-card"><strong>Review notes</strong><ul>{receipt.notes.map((note) => <li key={note}>{note}</li>)}</ul></div> : null}

        <div className="receipt-actions">
          <button type="button" className="primary" onClick={() => downloadReceipt(receipt)}>Export JSON receipt</button>
          <button type="button" className="ghost" onClick={closeDrawer}>Close</button>
        </div>

        <p className="privacy-note">This drawer keeps only the latest receipt metadata in browser memory. It does not persist raw source text, transformed prose, file bytes, or filenames.</p>
      </aside>
    </div>}
  </>;
}

import { scanText } from "@/lib/provenance/unicode";

export const ARTIFACT_KINDS = ["generic", "json", "agent-skill"] as const;
export type ArtifactKind = (typeof ARTIFACT_KINDS)[number];

export type ArtifactHygieneSeverity = "info" | "review" | "blocked";
export interface ArtifactHygieneFinding {
  code: string;
  severity: ArtifactHygieneSeverity;
  message: string;
  count: number;
}

export interface ArtifactProvenancePayload {
  version: "artifact-provenance-v1";
  artifactKind: ArtifactKind;
  artifactName: string | null;
  artifactVersion: string | null;
  canonicalization: "normalized-text-v1" | "stable-json-v1";
  artifactHash: string;
  previousArtifactHash: string | null;
  createdAt: string;
  hygiene: {
    status: "clean" | "review" | "blocked";
    findings: ArtifactHygieneFinding[];
  };
}

export interface ArtifactProvenanceReceipt extends ArtifactProvenancePayload {
  receiptHash: string;
}

export interface ArtifactVerificationResult {
  artifactMatches: boolean;
  receiptIntegrity: boolean;
  chainLinkWellFormed: boolean;
  expectedArtifactHash: string;
  actualArtifactHash: string;
  expectedReceiptHash: string;
  actualReceiptHash: string;
}

function normalizeText(input: string) {
  return input.replace(/^\uFEFF/u, "").replace(/\r\n?/gu, "\n");
}

function stableValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stableValue);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, item]) => [key, stableValue(item)]));
  }
  return value;
}

export function stableStringify(value: unknown): string {
  const result = JSON.stringify(stableValue(value));
  if (result === undefined) throw new Error("Artifact value cannot be canonically serialized.");
  return result;
}

export function canonicalizeArtifact(input: string, kind: ArtifactKind) {
  const normalized = normalizeText(input);
  const trimmed = normalized.trim();

  if (kind === "json") {
    return { text: stableStringify(JSON.parse(trimmed)), canonicalization: "stable-json-v1" as const };
  }

  if (kind === "agent-skill" && (trimmed.startsWith("{") || trimmed.startsWith("["))) {
    try {
      return { text: stableStringify(JSON.parse(trimmed)), canonicalization: "stable-json-v1" as const };
    } catch {
      // Skill artifacts may be Markdown/YAML/plain text. Fall back to normalized text.
    }
  }

  return { text: normalized, canonicalization: "normalized-text-v1" as const };
}

export async function sha256Hex(input: string) {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(input));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

function countMatches(text: string, expression: RegExp) {
  return Array.from(text.matchAll(expression)).length;
}

export function inspectArtifactHygiene(input: string, kind: ArtifactKind): ArtifactHygieneFinding[] {
  const findings: ArtifactHygieneFinding[] = [];
  const unicode = scanText(input);

  if (unicode.summary.safeToRemove > 0) {
    findings.push({
      code: "hidden_unicode_safe_remove",
      severity: "review",
      message: "Hidden or control Unicode that is normally safe to remove was detected.",
      count: unicode.summary.safeToRemove,
    });
  }
  if (unicode.summary.reviewRequired > 0) {
    findings.push({
      code: "hidden_unicode_review",
      severity: "review",
      message: "Unicode findings requiring human review were detected.",
      count: unicode.summary.reviewRequired,
    });
  }

  const credentialPatterns = [
    /\bsk-[A-Za-z0-9_-]{20,}\b/gu,
    /\bgh[pousr]_[A-Za-z0-9]{20,}\b/gu,
    /\bAKIA[0-9A-Z]{16}\b/gu,
    /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/gu,
  ];
  const credentials = credentialPatterns.reduce((sum, pattern) => sum + countMatches(input, pattern), 0);
  if (credentials > 0) {
    findings.push({
      code: "credential_like_material",
      severity: "blocked",
      message: "Credential-like material was detected. Rotate/remove secrets before publishing or sharing this artifact.",
      count: credentials,
    });
  }

  const trailingWhitespace = input.split(/\r?\n/u).filter((line) => /[ \t]+$/u.test(line)).length;
  if (trailingWhitespace > 0) {
    findings.push({
      code: "trailing_whitespace",
      severity: "info",
      message: "Lines with trailing whitespace were detected; canonical hashing preserves this content for non-JSON artifacts.",
      count: trailingWhitespace,
    });
  }

  if (kind === "agent-skill") {
    const lowered = input.toLowerCase();
    if (!/(^|\n)#{1,3}\s+.+/u.test(input) && !lowered.includes('"name"') && !lowered.includes("name:")) {
      findings.push({
        code: "skill_identity_missing",
        severity: "review",
        message: "The agent-skill artifact does not expose an obvious name/title field or heading.",
        count: 1,
      });
    }
    if (!lowered.includes("description") && !lowered.includes("instructions") && !lowered.includes("purpose")) {
      findings.push({
        code: "skill_contract_missing",
        severity: "review",
        message: "The agent-skill artifact does not expose an obvious description, instructions, or purpose contract.",
        count: 1,
      });
    }
  }

  return findings;
}

function hygieneStatus(findings: ArtifactHygieneFinding[]) {
  if (findings.some((item) => item.severity === "blocked")) return "blocked" as const;
  if (findings.some((item) => item.severity === "review")) return "review" as const;
  return "clean" as const;
}

export async function createArtifactReceipt(input: string, options: {
  kind: ArtifactKind;
  artifactName?: string;
  artifactVersion?: string;
  previousArtifactHash?: string;
  createdAt?: string;
}): Promise<ArtifactProvenanceReceipt> {
  const canonical = canonicalizeArtifact(input, options.kind);
  const artifactHash = await sha256Hex(canonical.text);
  const previous = options.previousArtifactHash?.trim().toLowerCase() || null;
  if (previous && !/^[a-f0-9]{64}$/u.test(previous)) throw new Error("Previous artifact hash must be a 64-character SHA-256 hex value.");

  const findings = inspectArtifactHygiene(input, options.kind);
  const payload: ArtifactProvenancePayload = {
    version: "artifact-provenance-v1",
    artifactKind: options.kind,
    artifactName: options.artifactName?.trim() || null,
    artifactVersion: options.artifactVersion?.trim() || null,
    canonicalization: canonical.canonicalization,
    artifactHash,
    previousArtifactHash: previous,
    createdAt: options.createdAt ?? new Date().toISOString(),
    hygiene: {
      status: hygieneStatus(findings),
      findings,
    },
  };
  return { ...payload, receiptHash: await sha256Hex(stableStringify(payload)) };
}

export async function verifyArtifactReceipt(input: string, receipt: ArtifactProvenanceReceipt): Promise<ArtifactVerificationResult> {
  const canonical = canonicalizeArtifact(input, receipt.artifactKind);
  const actualArtifactHash = await sha256Hex(canonical.text);
  const { receiptHash, ...payload } = receipt;
  const actualReceiptHash = await sha256Hex(stableStringify(payload));
  const previous = receipt.previousArtifactHash;

  return {
    artifactMatches: actualArtifactHash === receipt.artifactHash,
    receiptIntegrity: actualReceiptHash === receiptHash,
    chainLinkWellFormed: previous === null || /^[a-f0-9]{64}$/u.test(previous),
    expectedArtifactHash: receipt.artifactHash,
    actualArtifactHash,
    expectedReceiptHash: receiptHash,
    actualReceiptHash,
  };
}

export type ReadinessCheck = { configured: boolean; required: boolean };
const DEFAULT_SUPABASE_URL = "https://cikxzxxreryycfjumwsd.supabase.co";
const DEFAULT_SUPABASE_PUBLISHABLE_KEY = "sb_publishable_Jsa3NElnKfCPiXMes-CrXg_hthFy4r1";
const CONTROLLED_LAUNCH_TEST_PRICE_IDS = ["price_1UAXO6RB8OGmEnBwqpc4DaLs", "price_1UAXOFRB8OGmEnBwlAwgU1GS", "price_1UAXOQRB8OGmEnBwANqar75f"];
const CONTROLLED_LAUNCH_TEST_SUBSCRIPTION_PRICE_IDS = ["price_1UBmgJRB8OGmEnBwoUtRmBKb", "price_1UBmhIRB8OGmEnBwFEJNV4zF", "price_1UBmiARB8OGmEnBwgoMzZqbw"];
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/u;
const PLACEHOLDER_EMAIL = /(^|@)(example\.(com|invalid|org)|invalid|localhost)$|placeholder/iu;

function isVercelPreview() { return process.env.VERCEL_ENV === "preview"; }
function vercelOrigin() {
  const host = isVercelPreview()
    ? (process.env.VERCEL_BRANCH_URL || process.env.VERCEL_URL)
    : (process.env.VERCEL_PROJECT_PRODUCTION_URL || process.env.VERCEL_URL);
  return host ? `https://${host}` : undefined;
}
function hasOidc(request?: Request) {
  return Boolean(process.env.VERCEL_OIDC_TOKEN?.trim() || request?.headers.get("x-vercel-oidc-token")?.trim());
}

function isConfiguredOperationalEmail(value: string | undefined) {
  const email = value?.trim() ?? "";
  return EMAIL_PATTERN.test(email) && !PLACEHOLDER_EMAIL.test(email);
}

export function isDevelopmentTurnstileBypass() { return process.env.NODE_ENV !== "production" && process.env.TURNSTILE_DEV_BYPASS === "1"; }
export function isConfiguredSupportEmail(value: string | undefined) { return isConfiguredOperationalEmail(value); }
export function isConfiguredAdminOwnerEmail(value: string | undefined) { return isConfiguredOperationalEmail(value); }
export function publicAppOrigin(request?: Request) {
  const configured = process.env.NEXT_PUBLIC_APP_URL?.trim();
  const candidate = configured || vercelOrigin();
  if (candidate) {
    const url = new URL(candidate);
    if (!/^https?:$/u.test(url.protocol)) throw new Error("Application URL must use http or https.");
    if (process.env.NODE_ENV === "production" && url.protocol !== "https:") throw new Error("Application URL must use https in production.");
    return url.origin;
  }
  if (process.env.NODE_ENV === "production") throw new Error("Application URL is required in production.");
  return request ? new URL(request.url).origin : "http://localhost:3000";
}
export function readinessChecks(request?: Request): Record<string, ReadinessCheck> {
  const present = (name: string) => Boolean(process.env[name]?.trim());
  const stripeKey = process.env.STRIPE_SECRET_KEY?.trim() ?? "";
  const promoSecret = process.env.PROMO_FINGERPRINT_SECRET?.trim() ?? "";
  const supportEmail = process.env.NEXT_PUBLIC_SUPPORT_EMAIL?.trim() ?? "";
  const subscriptionPriceEnvConfigured = ["STRIPE_SUBSCRIPTION_PRICE_PLUS", "STRIPE_SUBSCRIPTION_PRICE_PRO", "STRIPE_SUBSCRIPTION_PRICE_STUDIO"].every((name) => /^price_/u.test(process.env[name]?.trim() ?? ""));
  const adminOwnerIdConfigured = /^[0-9a-f]{8}-[0-9a-f-]{27,}$/iu.test(process.env.ADMIN_OWNER_USER_ID?.trim() ?? "");
  const adminOwnerEmailConfigured = isConfiguredAdminOwnerEmail(process.env.ADMIN_OWNER_EMAIL);
  const adminOwnerConfigured = adminOwnerIdConfigured || adminOwnerEmailConfigured;
  const preview = isVercelPreview();
  const oidc = hasOidc(request);
  const stripeTestKey = stripeKey.startsWith("sk_test_") || stripeKey.startsWith("rk_test_");
  const publicSupabaseConfigured = (present("NEXT_PUBLIC_SUPABASE_URL") || Boolean(DEFAULT_SUPABASE_URL)) && (present("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY") || Boolean(DEFAULT_SUPABASE_PUBLISHABLE_KEY));
  const turnstileConfigured = (present("NEXT_PUBLIC_TURNSTILE_SITE_KEY") && present("TURNSTILE_SECRET_KEY")) || preview;
  const stripePricesConfigured = (present("STRIPE_PRICE_STARTER") && present("STRIPE_PRICE_PLUS") && present("STRIPE_PRICE_PRO")) || (stripeTestKey && CONTROLLED_LAUNCH_TEST_PRICE_IDS.every(Boolean));
  const subscriptionPricesConfigured = subscriptionPriceEnvConfigured || (stripeTestKey && CONTROLLED_LAUNCH_TEST_SUBSCRIPTION_PRICE_IDS.every(Boolean));
  const supportEmailConfigured = isConfiguredSupportEmail(supportEmail);
  return {
    appUrl: { configured: present("NEXT_PUBLIC_APP_URL") || Boolean(vercelOrigin()), required: true },
    supabasePublic: { configured: publicSupabaseConfigured, required: true },
    supabaseServer: { configured: present("SUPABASE_SECRET_KEY"), required: true },
    aiGateway: { configured: present("AI_GATEWAY_API_KEY") || oidc, required: true },
    turnstile: { configured: turnstileConfigured, required: true },
    rateLimitSalt: { configured: present("RATE_LIMIT_HASH_SALT") || oidc || (preview && Boolean(process.env.VERCEL_DEPLOYMENT_ID)), required: true },
    promoFingerprintSecret: { configured: promoSecret.length >= 32, required: true },
    supportEmail: { configured: supportEmailConfigured, required: true },
    stripeTestMode: { configured: stripeTestKey && present("STRIPE_WEBHOOK_SECRET") && stripePricesConfigured, required: true },
    subscriptionCatalog: { configured: subscriptionPricesConfigured, required: true },
    // Bootstrap configuration is intentionally optional after an owner has been
    // provisioned in ops.admin_users. /api/readiness combines this signal with
    // authoritative database state in its required adminOwner check.
    adminOwnerBootstrap: { configured: adminOwnerConfigured, required: false },
    cron: { configured: present("CRON_SECRET"), required: !preview },
  };
}
export function readinessSummary(request?: Request) { const checks = readinessChecks(request); const missing = Object.entries(checks).filter(([, check]) => check.required && !check.configured).map(([name]) => name); return { ready: missing.length === 0, checks, missing }; }

import { createHash, randomBytes } from "node:crypto";
import { createAdminClient } from "@/lib/supabase/admin";

export const DEVELOPER_API_KEY_PREFIX = "pc_sk_";
const MAX_ACTIVE_KEYS = 10;

type RpcResult = { data: unknown; error: { message: string } | null };
type RpcClient = { rpc: (name: string, args?: Record<string, unknown>) => Promise<RpcResult> };
export type DeveloperApiKeySummary = {
  id: string;
  name: string;
  prefix: string;
  createdAt: string;
  lastUsedAt: string | null;
  revokedAt: string | null;
};
export type DeveloperIdentity = { userId: string; keyId: string; prefix: string };

function client() { return createAdminClient() as unknown as RpcClient; }
function record(value: unknown) { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null; }
function stringValue(value: unknown) { return typeof value === "string" ? value : null; }
function mapKey(value: unknown): DeveloperApiKeySummary | null {
  const item = record(value);
  if (!item) return null;
  const id = stringValue(item.id);
  const name = stringValue(item.name);
  const prefix = stringValue(item.prefix);
  const createdAt = stringValue(item.createdAt);
  if (!id || !name || !prefix || !createdAt) return null;
  return {
    id,
    name,
    prefix,
    createdAt,
    lastUsedAt: stringValue(item.lastUsedAt),
    revokedAt: stringValue(item.revokedAt),
  };
}
async function rpc(name: string, args: Record<string, unknown> = {}) {
  const { data, error } = await client().rpc(name, args);
  if (error) throw new Error(error.message);
  return data;
}

export function developerApiKeyHash(secret: string) {
  return createHash("sha256").update(secret, "utf8").digest("hex");
}

export function generateDeveloperApiKeyMaterial() {
  const secret = `${DEVELOPER_API_KEY_PREFIX}${randomBytes(32).toString("base64url")}`;
  return { secret, prefix: secret.slice(0, 17), hash: developerApiKeyHash(secret) };
}

export function developerBearerToken(request: Pick<Request, "headers">) {
  const authorization = request.headers.get("authorization")?.trim() ?? "";
  const match = /^Bearer\s+(.+)$/iu.exec(authorization);
  if (!match) return null;
  const token = match[1].trim();
  if (!token.startsWith(DEVELOPER_API_KEY_PREFIX) || token.length < 35 || token.length > 100) return null;
  return token;
}

export async function createDeveloperApiKey(userId: string, name: string) {
  const material = generateDeveloperApiKeyMaterial();
  const data = record(await rpc("developer_api_key_create", {
    p_user_id: userId,
    p_name: name,
    p_prefix: material.prefix,
    p_hash: material.hash,
  }));
  if (!data) throw new Error("developer_api_key_create_failed");
  const summary = mapKey({ ...data, lastUsedAt: null, revokedAt: null });
  if (!summary) throw new Error("developer_api_key_create_invalid_response");
  return { ...summary, secret: material.secret };
}

export async function listDeveloperApiKeys(userId: string) {
  const data = await rpc("developer_api_key_list", { p_user_id: userId });
  if (!Array.isArray(data)) return [];
  return data.map(mapKey).filter((item): item is DeveloperApiKeySummary => Boolean(item));
}

export async function revokeDeveloperApiKey(userId: string, keyId: string) {
  return (await rpc("developer_api_key_revoke", { p_user_id: userId, p_key_id: keyId })) === true;
}

export async function authenticateDeveloperRequest(request: Pick<Request, "headers">): Promise<DeveloperIdentity | null> {
  const token = developerBearerToken(request);
  if (!token) return null;
  const data = record(await rpc("developer_api_key_resolve", { p_hash: developerApiKeyHash(token) }));
  if (!data) return null;
  const userId = stringValue(data.userId);
  const keyId = stringValue(data.keyId);
  const prefix = stringValue(data.prefix);
  return userId && keyId && prefix ? { userId, keyId, prefix } : null;
}

export async function getDeveloperPhase9Status() {
  return record(await rpc("developer_phase9_status"));
}

